// Or inside a controller/area using the attribute
[AttributeUsage(AttributeTargets.Class | AttributeTargets.Method)]
public class DisableClientValidationAttribute : Attribute, IAsyncPageFilter, IAsyncActionFilter
{
    public async Task OnPageHandlerSelectionAsync(PageHandlerExecutingContext context) { }
    public async Task OnPageHandlerExecutedAsync(PageHandlerExecutedContext context) { }
}

